class RulesetManifest(BaseModel):
    """
    rulesets/<ID>/manifest.yaml (SPEC 3.4). Schema version 1.2.0 (1.1.0: optional terminology_tables, the TERM-2 follow-up; 1.2.0: optional terminology_refused, E-TERM-3).
    """

    model_config = ConfigDict(
        extra="forbid",
        populate_by_name=True,
    )
    id: str = Field(..., pattern="^[A-Za-z0-9_-]{1,16}$")
    kind: Literal["trial", "nhi", "cohort"]
    title: str
    trial_alias: str | None = None
    sponsor: str | None = None
    version: str = Field(..., pattern="^[0-9]+\\.[0-9]+\\.[0-9]+$")
    status: Literal["draft", "approved"] = "draft"
    source_documents: list[str] | None = None
    protocol_version: str | None = None
    protocol_date: date_aliased | None = None
    """
    the date of the protocol version these criteria come from (D-364)
    """
    effective_from: date_aliased | None = None
    """
    the first site day this criteria version screens (D-364, LIFE-009): until then the box keeps screening on the version before it
    """
    irb_reference: str | None = Field(None, max_length=64)
    """
    the IRB approval number of this protocol version as the approver typed it (D-364): a record printed with the approval, not a gate (D-311)
    """
    irb_approved_on: date_aliased | None = None
    """
    the day the IRB approved this protocol version (D-364), a record
    """
    language: str | None = None
    index_date_rule: Literal["run_date", "month_end"]
    library: str | None = None
    """
    CQL library name TB_<RULESET>_v<major>_<minor>
    """
    criteria: list[str]
    """
    criterion ids in funnel/report order
    """
    scopes: Scopes
    routing: Routing
    thresholds: RulesetThresholds
    models: RulesetModels | None = None
    review: ManifestReview | None = None
    equivalence: EquivalenceSummary | None = None
    variants: dict[str, str] | None = None
    """
    named default sensitivity variants, e.g. bmi: '24,25,27'
    """
    twpas: TwpasConfig | None = None
    docx_template: str | None = None
    """
    relative path of the Jinja2 docx application template
    """
    cohort: CohortConfig | None = None
    population: PopulationSpec | None = None
    nct_id: str | None = None
    terminology_release: str | None = Field(None, pattern="^TR-[0-9a-f]{12}$")
    """
    the terminology release the ruleset was compiled against (D-301): a run against another release is refused until it is recompiled
    """
    prompt_pins: dict[str, PromptPin] | None = None
    """
    the prompts the approved ruleset runs with, by prompt id (D-318): SCREEN runs the pinned version and text until the investigator re-approves; a newer registered version puts the study in approval needed
    """
    terminology_tables: list[TerminologyTable] | None = None
    """
    TERM-2 follow-up: each table loaded at install (a site list, the NHI lists, ICD-10-PCS, a licensed table, a later ICD-10-CM release) the compile read, beside terminology_release (the shipped Parquet). Absent: no loaded table was read. Approval is blocked while the box's loaded tables differ from these
    """
    derived_pins: dict[str, DerivedPin] | None = None
    """
    the score definitions the approved ruleset's criteria follow, by engine score (D-442): a definition of another version or text on the box puts the study in approval needed, and until then screening reads those scores as unknown
    """
    source_last_update: str | None = None
    terminology_refused: list[RefusedTable] | None = None
    """
    the installed code tables the compile could not read (E-TERM-3, D-1048): each by its table name and why; while one is a site list (site_*), approval is refused
    """


