class CriterionIR(BaseModel):
    """
    One eligibility criterion (SPEC 3.3). Schema version 1.3.0 (1.1.0: derived egfr_ckd_epi and egfr_jsn, D-149; 1.2.0: derived cdai and sdai, D-189; 1.3.0: optional provenance, the model calls the criterion was extracted by, D-989).
    """

    model_config = ConfigDict(
        extra="forbid",
        populate_by_name=True,
    )
    id: str = Field(
        ..., pattern="^[A-Z0-9]+(-[A-Z0-9]+)*-(INC|EXC|REN|DOC)-[0-9]{2,3}$"
    )
    ruleset: str
    text: str
    label: str | None = None
    """
    short display label for funnels and spreadsheets
    """
    source_ref: str | None = None
    """
    section/page in source document
    """
    kind: Literal["inclusion", "exclusion", "renewal", "documentation"]
    class_: Literal["structured", "note", "human", "mixed"] = Field(..., alias="class")
    """
    structured: coded data decide; note: the model reads notes; human: asked at screening; mixed: coded data decide when they can, the notes decide the rest (D-98)
    """
    time_sensitive: bool = False
    logic: Atom | BoolExpr = Field(..., title="Expr")
    fallback: str | None = None
    note_question: str | None = None
    """
    for class=note or mixed: the yes/no question put to the LLM
    """
    note_question_source: str | None = None
    """
    the question as the model extracted it, when the compiler rewrote a negated exclusion question to its positive form (D-98)
    """
    human_question: str | None = None
    action: str | None = None
    """
    suggested action when unknown/pending (e.g. 'order creatinine')
    """
    suggested_order: str | None = None
    """
    for documentation criteria: order code/name that closes the gap
    """
    flags: list[str] | None = None
    """
    e.g. needs_review, equivalence_fail, concept_unmapped
    """
    review: CriterionReview | None = None
    provenance: CriterionProvenance | None = None


